(100, 'Tiệm Món Việt Tuyệt Hảo 1', 'Thưởng thức hương vị đích thực tại Tiệm Món Việt Tuyệt Hảo 1. Chúng tôi mang đến trải nghiệm không gian sang trọng, nguyên liệu tươi ngon nhất và phong cách phục vụ đẳng cấp. Rất hân hạnh được đón tiếp quý khách.', '200 Đường Mock, Quận 1, TP. HCM', '0909000100', 10.0, 50000.00, 50, 'ACTIVE', 100, 3.7, 'https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?w=800', 347633.45, 1, NOW(), NOW()),
(101, 'Góc Món Việt Gia Truyền 2', 'Thưởng thức hương vị đích thực tại Góc Món Việt Gia Truyền 2. Chúng tôi mang đến trải nghiệm không gian sang trọng, nguyên liệu tươi ngon nhất và phong cách phục vụ đẳng cấp. Rất hân hạnh được đón tiếp quý khách.', '201 Đường Mock, Quận 2, TP. HCM', '0909000101', 10.0, 50000.00, 50, 'ACTIVE', 101, 3.6, 'https://images.unsplash.com/photo-1555396273-367ea4eb4db5?w=800', 465790.29, 1, NOW(), NOW()),
(102, 'Nhà hàng Món Việt Premium 3', 'Thưởng thức hương vị đích thực tại Nhà hàng Món Việt Premium 3. Chúng tôi mang đến trải nghiệm không gian sang trọng, nguyên liệu tươi ngon nhất và phong cách phục vụ đẳng cấp. Rất hân hạnh được đón tiếp quý khách.', '202 Đường Mock, Quận 3, TP. HCM', '0909000102', 10.0, 50000.00, 50, 'ACTIVE', 102, 3.6, 'https://images.unsplash.com/photo-1514933651103-005eec06c04b?w=800', 298921.52, 1, NOW(), NOW()),
(103, 'Quán Món Việt Chính Hiệu 4', 'Thưởng thức hương vị đích thực tại Quán Món Việt Chính Hiệu 4. Chúng tôi mang đến trải nghiệm không gian sang trọng, nguyên liệu tươi ngon nhất và phong cách phục vụ đẳng cấp. Rất hân hạnh được đón tiếp quý khách.', '203 Đường Mock, Quận 4, TP. HCM', '0909000103', 10.0, 50000.00, 50, 'ACTIVE', 103, 3.8, 'https://images.unsplash.com/photo-1552566626-52f8b828add9?w=800', 274754.10, 1, NOW(), NOW()),
(104, 'Bếp Món Việt Hoàng Gia 5', 'Thưởng thức hương vị đích thực tại Bếp Món Việt Hoàng Gia 5. Chúng tôi mang đến trải nghiệm không gian sang trọng, nguyên liệu tươi ngon nhất và phong cách phục vụ đẳng cấp. Rất hân hạnh được đón tiếp quý khách.', '204 Đường Mock, Quận 5, TP. HCM', '0909000104', 10.0, 50000.00, 50, 'ACTIVE', 104, 4.8, 'https://images.unsplash.com/photo-1414235077428-338989a2e8c0?w=800', 295253.27, 1, NOW(), NOW()),
(105, 'Nhà hàng ẩm thực Món Việt Bình Dân 6', 'Thưởng thức hương vị đích thực tại Nhà hàng ẩm thực Món Việt Bình Dân 6. Chúng tôi mang đến trải nghiệm không gian sang trọng, nguyên liệu tươi ngon nhất và phong cách phục vụ đẳng cấp. Rất hân hạnh được đón tiếp quý khách.', '205 Đường Mock, Quận 1, TP. HCM', '0909000105', 10.0, 50000.00, 50, 'ACTIVE', 105, 4.8, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=800', 451271.31, 1, NOW(), NOW()),
